import java.util.*;

public class Main {
    static int n, t;
    static int[] dx = {-1, 0, 1, 0, 0};
    static int[] dy = {0, 1, 0, -1, 0};

    static class Pkt {
        int x, y;
        Pkt(int x, int y) { this.x = x; this.y = y; }
    }

    static class Kraw {
        int a, res;
        Kraw(int a, int res) { this.a = a; this.res = res; }
    }

    static boolean ok(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine(); // consume newline
        char[][] nau = new char[n][n];
        char[][] pom = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                nau[i][j] = line.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                pom[i][j] = line.charAt(j);
            }
        }

        int[][] odl = new int[n][n];
        for (int i = 0; i < n; i++) Arrays.fill(odl[i], 1000);

        Pkt start = null;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (nau[i][j] == 'Z') {
                    start = new Pkt(i, j);
                }
            }
        }

        Queue<Pkt> Q = new LinkedList<>();
        odl[start.x][start.y] = 0;
        Q.add(start);
        while (!Q.isEmpty()) {
            Pkt akt = Q.poll();
            for (int i = 0; i < 4; i++) {
                int nx = akt.x + dx[i];
                int ny = akt.y + dy[i];
                if (ok(nx, ny) && nau[nx][ny] >= '0' && nau[nx][ny] <= '9' && odl[nx][ny] == 1000) {
                    odl[nx][ny] = odl[akt.x][akt.y] + 1;
                    Q.add(new Pkt(nx, ny));
                }
            }
        }

        // max N is at most 10 from original code, but we allocate 10 as fixed size
        boolean[][][][][] moge = new boolean[60][10][10][10][10];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 5; k++) {
                    int l = i + dx[k], m = j + dy[k];
                    if (ok(l, m) && nau[i][j] >= '0' && nau[i][j] <= '9' && nau[l][m] >= '0' && nau[l][m] <= '9') {
                        moge[0][i][j][l][m] = true;
                    }
                }
            }
        }

        for (int i = 0; i <= t - 2; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < n; l++) {
                        for (int m = 0; m < n; m++) {
                            if (!moge[i][j][k][l][m]) continue;
                            for (int o = 0; o < 5; o++) {
                                int p = l + dx[o], r = m + dy[o];
                                if (ok(p, r) && nau[p][r] >= '0' && nau[p][r] <= '9' && odl[l][m] >= i + 2 && odl[p][r] >= i + 2) {
                                    moge[i + 1][j][k][p][r] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        ArrayList<Pkt> a = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (nau[i][j] >= '0' && nau[i][j] <= '9') {
                    a.add(new Pkt(i, j));
                }
            }
        }

        int wie = 2 * a.size() + 2;
        ArrayList<ArrayList<Kraw>> G = new ArrayList<>(wie);
        for (int i = 0; i < wie; i++) {
            G.add(new ArrayList<>());
        }

        for (int i = 0; i < a.size(); i++) {
            // source to left
            G.get(0).add(new Kraw(i + 1, nau[a.get(i).x][a.get(i).y] - '0'));
            G.get(i + 1).add(new Kraw(0, 0));
            // right to sink
            G.get(a.size() + 1 + i).add(new Kraw(wie - 1, pom[a.get(i).x][a.get(i).y] - '0'));
            G.get(wie - 1).add(new Kraw(a.size() + 1 + i, 0));
        }

        for (int i = 0; i < a.size(); i++) {
            for (int j = 0; j < a.size(); j++) {
                boolean ok = false;
                for (int k = 0; k <= t - 1; k++) {
                    if (moge[k][a.get(i).x][a.get(i).y][a.get(j).x][a.get(j).y]) {
                        ok = true;
                        break;
                    }
                }
                if (ok) {
                    G.get(i + 1).add(new Kraw(a.size() + 1 + j, 1000));
                    G.get(a.size() + 1 + j).add(new Kraw(i + 1, 0));
                }
            }
        }

        int odp = 0;
        while (true) {
            boolean[] odw = new boolean[wie];
            odw[0] = true;
            Queue<Integer> Q2 = new LinkedList<>();
            Q2.add(0);
            int[] pop = new int[wie];
            Arrays.fill(pop, -1);
            while (!Q2.isEmpty()) {
                int akt = Q2.poll();
                for (Kraw kraw : G.get(akt)) {
                    if (!odw[kraw.a] && kraw.res > 0) {
