            int cur = wie - 1;
            while (cur != -1) {
                path.add(cur);
                cur = pop[cur];
            }
            Collections.reverse(path);

            int flow = 1000;
            for (int i = 0; i < path.size() - 1; i++) {
                int u = path.get(i), v = path.get(i + 1);
                for (Kraw kraw : G.get(u)) {
                    if (kraw.a == v) {
                        flow = Math.min(flow, kraw.res);
                    }
                }
            }
            odp += flow;

            for (int i = 0; i < path.size() - 1; i++) {
                int u = path.get(i), v = path.get(i + 1);
                for (Kraw kraw : G.get(u)) {
                    if (kraw.a == v) {
                        kraw.res -= flow;
                    }
                }
                for (Kraw kraw : G.get(v)) {
                    if (kraw.a == u) {
                        kraw.res += flow;
                    }
                }
            }
        }

        System.out.println(odp);
    }
}
